-- study 콘텐츠 내 LaTeX 수식 복구
-- V1 마이그레이션 SQL을 MySQL 기본 백슬래시 이스케이프 규칙으로 실행하면서
-- \\text, \\times, \\sim, \\le, \\ge, \\mid, \\ll, \\log, \\min, \\max, \\left/\\right,
-- \\; 등 한 글자로 시작하는 LaTeX 명령이 이스케이프 문자로 오인되어(\\t -> 탭, \\r -> 캐리지리턴,
-- 그 외는 백슬래시가 그냥 삭제됨) 수식이 깨진 상태로 저장되어 있던 것을 복구한다.
-- 값은 이스케이프 문제를 원천 차단하기 위해 16진 리터럴(X'...')로 기록한다.

UPDATE `study` SET `content_markdown` = X'' WHERE `id` = 19;

